        dev_err(&dev->udev->dev, "failed to register device\n");
        goto error;
    }

    return 0;

error:
    lego_usb_tower_cleanup(dev);
    kfree(dev);
    return retval;
}

int lego_usb_tower_init(struct usb_interface *interface, const struct usb_device_id *id) {
    struct lego_usb_tower_dev *dev;
    int ret;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    spin_lock_init(&dev->lock);

    dev->interface = interface;
    dev->udev = usb_get_dev(interface_to_usbdev(interface));

    usb_set_intfdata(interface, dev);

    ret = usb_find_altsetting(interface->cur_altsetting, LEGO_USB_TOWER_EP_TYPE, &dev->ep);
    if (ret < 0)
        goto error_free_dev;

    ret = lego_usb_tower_get_firmware_version(dev);
    if (ret < 0)
        goto error_free_dev;

    ret = lego_usb_tower_register_device(dev);
    if (ret < 0)
        goto error_free_dev;

    return 0;

error_free_dev:
    usb_put_dev(dev->udev);
    kfree(dev);
    return ret;
}

int lego_usb_tower_init(struct usb_interface *interface, const struct usb_device_id *id) {
    struct lego_usb_tower_dev *dev;
    int retval = -ENOMEM;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        goto error;

    spin_lock_init(&dev->lock);

    dev->interface = interface;
    dev->udev = usb_get_dev(interface_to_usbdev(interface));

    usb_fill_int_urb(&dev->irq_urb, dev->udev,
                     usb_rcvintpipe(dev->udev, LEGO_USB_TOWER_EP_IRQ),
                     dev->irq_buffer, LEGO_USB_TOWER_IRQ_SIZE,
                     lego_usb_tower_irq, dev, dev->irq_interval);

    dev->irq_urb.transfer_flags |= URB_NO_TRANSFER_DMA_MAP;

    dev->ctrl_urb = usb_alloc_urb(0, GFP_KERNEL);
    if (!dev->ctrl_urb)
        goto error_free_dev;

    usb_fill_control_urb(dev->ctrl_urb, dev->udev,
                         usb_sndctrlpipe(dev->udev, 0),
                         NULL, NULL, 0, NULL, dev);

    if ((retval = usb_register_dev(dev, &lego_usb_tower_class))) {
        dev_err(&interface->dev, "USB device registration failed. Error number %d\n", retval);
        goto error_free_ctrl_urb;
    }

    return 0;

error_free_ctrl_urb:
    usb_free_urb(dev->ctrl_urb);
error_free_dev:
    kfree(dev);
error:
    return retval;
}

int lego_usb_tower_init(struct usb_interface *interface, const struct usb_device_id *id) {
    struct lego_usb_tower_dev *dev;
    int ret;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    mutex_init(&dev->lock);

    dev->interface = interface;
    dev->usb_dev = interface_to_usbdev(interface);

    ret = usb_set_interface(dev->usb_dev, 0, 0);
    if (ret < 0)
        goto error_free_dev;

    ret = usb_fill_control_urb(&dev->ctrl_urb, dev->usb_dev,
                               usb_sndctrlpipe(dev->usb_dev, 0),
                               dev->ctrl_req, dev->ctrl_buf,
                               LEGO_USB_CTRL_SIZE, NULL, dev);
    if (!dev->ctrl_urb)
        goto error_free_dev;

    ret = usb_register_dev(dev, &lego_usb_tower_class);
    if (ret < 0)
        goto error_free_dev;

    usb_set_drvdata(interface, dev);

    return 0;

error_free_dev:
    kfree(dev);
    return ret;
}
